SELECT r.id, r.user_id, r.conversation_id, r.turn_id, r.message_id, r.tool_name, r.title, r.arguments, r.metadata, r.status, r.decision, r.expires_at, r.timed_out_at, r.approved_by_user_id, r.approved_at, r.executed_at, r.error_message, r.created_at, r.updated_at FROM (SELECT data_rows.id, data_rows.should_delete, data_rows.user_id, data_rows.conversation_id, data_rows.turn_id, data_rows.message_id, data_rows.tool_name, data_rows.title, data_rows.arguments, data_rows.metadata, data_rows.status, data_rows.decision, data_rows.expires_at, data_rows.timed_out_at, data_rows.approved_by_user_id, data_rows.approved_at, data_rows.executed_at, data_rows.error_message, data_rows.created_at, data_rows.updated_at FROM  (SELECT 0 AS should_delete, `id`, `user_id`, `conversation_id`, `turn_id`, `message_id`, `tool_name`, `title`, `arguments`, `metadata`, `status`, `decision`, `expires_at`, `timed_out_at`, `approved_by_user_id`, `approved_at`, `executed_at`, `error_message`, `created_at`, `updated_at` FROM tool_approval_queue)  data_rows) r WHERE $criteria.CompositeIn("r", $WriterKeys)